package com.miniforce.dto;
import com.miniforce.model.*; import jakarta.validation.constraints.*; import java.time.*; import java.util.*;
public final class ContestDtos { private ContestDtos(){} public record ContestRequest(@NotBlank @Size(max=180) String title,String description,@NotNull ContestStatus status,@NotNull Instant startsAt,@NotNull Instant endsAt,boolean rated,Set<Long> problemIds) {} public record ContestResponse(Long id,String title,String description,ContestStatus status,Instant startsAt,Instant endsAt,boolean rated) { public static ContestResponse from(Contest c){return new ContestResponse(c.getId(),c.getTitle(),c.getDescription(),c.getStatus(),c.getStartsAt(),c.getEndsAt(),c.isRated());} } public record ContestProblemResponse(Long id,String slug,String title,Difficulty difficulty,int points){} public record ContestLeaderboardEntry(int rank, UserResponse user, int score){} }
